use std::fmt::Write;

use super::field_name;
use crate::{
    output::RawOutput,
    schema::{AstType, FieldLocation, Schema},
};

pub(crate) fn visitor_keys(schema: &Schema) -> Vec<RawOutput> {
    let mut js = String::from(
        "// Generated by ast_tools. Do not edit.\nexport const visitorKeys = Object.freeze({\n",
    );
    let mut dts = String::from(
        "// Generated by ast_tools. Do not edit.\nexport declare const visitorKeys: {\n",
    );
    let mut children = String::from(
        "// Generated by ast_tools. Do not edit.\nimport { Field } from '#protocol/internal';\n",
    );
    let mut readers = Vec::new();
    const HOT: &[&str] = &[
        "MemberExpression",
        "CallExpression",
        "ExpressionStatement",
        "VariableDeclarator",
        "BinaryExpression",
        "LogicalExpression",
        "AssignmentExpression",
    ];
    for ty in &schema.types {
        let AstType::Struct(ast) = ty else { continue };
        let name = &ast.name;
        let fields = ast
            .fields
            .iter()
            .enumerate()
            .filter_map(|(index, field)| {
                let (ty, optional) = match &schema.types[field.type_id] {
                    AstType::Option(option) => (&schema.types[option.inner_type_id], true),
                    ty => (ty, false),
                };
                matches!(
                    ty,
                    AstType::Struct(_) | AstType::Enum(_) | AstType::SubRange(_)
                )
                .then(|| {
                    (
                        field_name(&field.name),
                        ast.layout.fields[index],
                        matches!(ty, AstType::SubRange(_)),
                        optional,
                    )
                })
            })
            .collect::<Vec<_>>();
        let keys = fields.iter().map(|(key, _, _, _)| key).collect::<Vec<_>>();
        writeln!(js, "  {name}: Object.freeze({keys:?}),").unwrap();
        writeln!(dts, "  readonly {name}: readonly string[];").unwrap();
        if !HOT.contains(&name.as_str()) || fields.is_empty() {
            readers.push("null".to_owned());
            continue;
        }
        let reader = format!("read{name}");
        readers.push(reader.clone());
        writeln!(
            children,
            "\nfunction {reader}(ast, id, walker, plan, kind) {{"
        )
        .unwrap();
        children.push_str("  let version = ast._editVersion;\n  let row = ast.row(id), payload = ast._payloadAt(id, row);\n  let view = row === -1 ? ast._view : ast._arena.view;\n");
        for (index, (key, location, list, optional)) in fields.iter().enumerate() {
            if *list {
                writeln!(
                    children,
                    "  if (walker.visitListField(id, Field.{key}, plan.children[{index}])) {{ return true; }}"
                )
                .unwrap();
            } else {
                children.push_str("  {\n");
                match location {
                    FieldLocation::Payload { offset, .. } => {
                        writeln!(children, "    const child = ast.childAt(id, payload + {offset}, {optional}, view);").unwrap();
                    }
                    FieldLocation::Extra { index } => {
                        writeln!(
                            children,
                            "    const start = view.getUint32(payload + {}, true);",
                            ast.layout.extra_start_offset().unwrap()
                        )
                        .unwrap();
                        writeln!(children, "    const extra = start + {index};").unwrap();
                        children.push_str("    const limit = start < ast._extraCount ? ast._extraCount : ast.extraDataCount;\n    if (extra + 1 > limit) { throw new RangeError(\"AST extra-data reference out of bounds\"); }\n    const extraView = extra < ast._extraCount ? ast._view : ast._arena.view;\n    const offset = extra < ast._extraCount ? ast._extra + extra * 4 : ast._arena.extraAddress(extra);\n");
                        writeln!(
                            children,
                            "    const child = ast.childAt(id, offset, {optional}, extraView);"
                        )
                        .unwrap();
                    }
                }
                writeln!(children, "    if (child !== 0xffffffff && walker.visitScalarId(child, id, Field.{key})) {{ return true; }}\n  }}").unwrap();
            }
            writeln!(children, "  if (ast._editVersion !== version) {{\n    version = ast._editVersion;\n    const liveKind = ast._kindAt(id);\n    if (liveKind !== kind) {{ return walker.visitRemaining(id, liveKind, plan, {}); }}\n    row = ast.row(id); payload = ast._payloadAt(id, row); view = row === -1 ? ast._view : ast._arena.view;\n  }}", index + 1).unwrap();
        }
        children.push_str("  return false;\n}\n");
    }
    js.push_str("});\n");
    dts.push_str("};\nexport type NodeType = keyof typeof visitorKeys;\n");
    children.push_str("\nexport const childVisitors = [\n");
    for reader in readers {
        writeln!(children, "  {reader},").unwrap();
    }
    children.push_str("];\n");
    vec![
        RawOutput {
            path: "npm/core-ffi2/src-js/walker/child-visitors.js".into(),
            content: children.into_bytes(),
        },
        RawOutput {
            path: "npm/core-ffi2/src-js/walker/visitor-keys.js".into(),
            content: js.into_bytes(),
        },
        RawOutput {
            path: "npm/core-ffi2/src-js/walker/visitor-keys.d.ts".into(),
            content: dts.into_bytes(),
        },
    ]
}
